  "Payroll Liabilities and Payments": [{"q": "What should the payroll liability balance do after liabilities are paid?", "opts": ["Return to zero", "Stay the same", "Increase", "Become negative"], "correct": 0, "exp": "Paying the liability clears the balance."}, {"q": "What happens if a liability payment is recorded as a general expense?", "opts": ["The cost is doubled and the liability never clears", "Nothing", "The liability doubles", "Tax is refunded"], "correct": 0, "exp": "The expense was already recorded at the pay run, so this records it twice."}, {"q": "A liability account shows three months of accumulated deductions. What does this suggest?", "opts": ["Payments were missed or recorded incorrectly", "Payroll is efficient", "Staff were overpaid", "Nothing unusual"], "correct": 0, "exp": "A cleared liability should not accumulate across months."}],
